import {esc,input,select,button} from '../phase4/ui.js';
import * as G from './b24-geometry.js';import {zones,gridPoint,gridIndex,mirrorTargets,goalImage,inspect} from './b24-model.js';
const btn=(a,l,x='')=>button('p24-'+a,l,x),f=(k,l,v)=>input(k,l,v).replace('maxlength="2000"','maxlength="1500"'),sel=(k,l,v,o)=>select(k,l,v,o),note=s=>`<p class="p24-note">${s}</p>`,card=s=>`<div class="p24-card">${s}</div>`,fmt=n=>Number.isFinite(n)?String(Math.round(n*100)/100):'—';
const fold=(v,yes)=>yes?`<details class="p24-fold"><summary>查看或修改刚才的操作</summary>${v}</details>`:v;
const qs=(t,m)=>(t.questions||[]).map((q,i)=>q.options?sel('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i])).join('');
const done=(t,m)=>inspect(t,{...m,answers:(t.questions||[]).map(q=>String(q.value))}).correct;
const line=(a,b,attrs='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" ${attrs}/>`;
const polygon=(ps,attrs='')=>`<polygon points="${ps.map(p=>p.join(',')).join(' ')}" ${attrs}/>`;
const svg=(body,label,view='0 0 700 450')=>`<svg class="p24-svg" viewBox="${view}" role="img" aria-label="${esc(label)}">${body}</svg>`;
const name=i=>String.fromCharCode(65+i);
function layout(t){const[xmin,xmax,ymin,ymax]=t.domain,w=700,h=450,s=Math.min((w-100)/(xmax-xmin),(h-80)/(ymax-ymin)),left=(w-(xmax-xmin)*s)/2,bottom=(h+(ymax-ymin)*s)/2;return{map:([x,y])=>[left+(x-xmin)*s,bottom-(y-ymin)*s],s,left,bottom,xmin,xmax,ymin,ymax};}
function gridBase(t,clickable=false){const L=layout(t),{map,s,xmin,xmax,ymin,ymax}=L;let out='';for(let x=xmin;x<=xmax;x++){const a=map([x,ymin]),b=map([x,ymax]);out+=line(a,b,`stroke="${x===0?'#719582':'#dbe3d6'}" stroke-width="${x===0?2.5:1}"`);out+=`<text x="${a[0]}" y="${a[1]+20}" text-anchor="middle">${x}</text>`;}for(let y=ymin;y<=ymax;y++){const a=map([xmin,y]),b=map([xmax,y]);out+=line(a,b,`stroke="${y===0?'#719582':'#dbe3d6'}" stroke-width="${y===0?2.5:1}"`);out+=`<text x="${a[0]-11}" y="${a[1]+4}" text-anchor="end">${y}</text>`;}if(t.axisNames)out+=`<text x="${map([xmax,ymin])[0]}" y="${map([xmax,ymin])[1]+32}" text-anchor="end">${esc(t.axisNames[0])}</text><text x="${map([xmin,ymax])[0]}" y="${map([xmin,ymax])[1]-12}">${esc(t.axisNames[1])}</text>`;if(clickable)for(let y=ymin;y<=ymax;y++)for(let x=xmin;x<=xmax;x++){const[p,q]=map([x,y]);out+=`<circle cx="${p}" cy="${q}" r="${Math.min(s*.4,10)}" fill="transparent" class="p24-hit" data-x="p24-dot" data-index="${gridIndex(t,x,y)}"><title>(${x},${y})</title></circle>`;}return{...L,svg:out};}
function marks(ps,map,color='#be8153',prefix='',start=0){return ps.map((p,i)=>{const[x,y]=map(p);return`<circle cx="${x}" cy="${y}" r="6" fill="${color}" stroke="#fff" stroke-width="2"/><text x="${x+8}" y="${y-8}">${name(i+start)}${prefix}</text>`;}).join('');}
function showPoly(ps,map,attrs=''){return ps.length>=3?polygon(ps.map(map),attrs):ps.length===2?line(map(ps[0]),map(ps[1]),attrs):'';}
function gridView(t,b){const {svg:base,map}=gridBase(t,true),given=t.given||[],all=[...given,...b.placed];let s=base;if(b.closed)s+=showPoly(all,map,'fill="#dfc8a6" fill-opacity=".35" stroke="#557e6e" stroke-width="3"');else if(all.length>1&&t.close)s+=all.slice(1).map((p,i)=>line(map(all[i]),map(p),'stroke="#8caa9a" stroke-width="2" stroke-dasharray="5 4"')).join('');s+=marks(given,map,'#728fa8')+marks(b.placed,map,'#bc8052','',given.length);return svg(s,'可点交点的坐标图')+note(`已放 ${b.placed.length} 个新点。点交点，或在下面输入两个数。`);}
function readView(t,b){const {svg:base,map}=gridBase(t),pts=t.points;let s=base;if(t.polygon)s+=showPoly(pts,map,'fill="#e2c6a2" fill-opacity=".3" stroke="#749785" stroke-width="3"');s+=marks(pts,map,'#b7794d');return svg(s,'有字母标记的坐标图')+note(`已记 ${b.readings.filter(Boolean).length}/${pts.length} 个点。横轴在前，纵轴在后。`);}
function distanceView(t,b){const {svg:base,map}=gridBase(t);let s=base;t.segments.forEach(([a,c],i)=>{const p=t.points[a],q=t.points[c],mid=map([(p[0]+q[0])/2,(p[1]+q[1])/2]);s+=line(map(p),map(q),`stroke="${b.measured.includes(i)?'#c5844e':'#88a99a'}" stroke-width="5"`);if(b.measured.includes(i))s+=`<text x="${mid[0]+8}" y="${mid[1]-8}">${fmt(G.dist(p,q))} 格</text>`;});s+=marks(t.points,map,'#b7794d');if(t.labels)t.labels.forEach((v,i)=>{const[x,y]=map(t.points[i]);s+=`<text x="${x+8}" y="${y+19}">${esc(v)}</text>`;});return svg(s,'可量的线段与端点')+note('一格的长度由题目决定；跨过0的部分都要计入。');}
function transformView(t,b){const {svg:base,map,xmin,xmax,ymin,ymax}=gridBase(t),original=t.shape;let s=base;const g=t.goal;if(g.kind==='mirror'){if(g.line==='x')s+=line(map([xmin,0]),map([xmax,0]),'stroke="#b68153" stroke-width="3" stroke-dasharray="7 5"');if(g.line==='y')s+=line(map([0,ymin]),map([0,ymax]),'stroke="#b68153" stroke-width="3" stroke-dasharray="7 5"');if(g.line==='y=x'){const lo=Math.max(xmin,ymin),hi=Math.min(xmax,ymax);s+=line(map([lo,lo]),map([hi,hi]),'stroke="#b68153" stroke-width="3" stroke-dasharray="7 5"');}if(g.line==='y=-x'){const lo=Math.max(xmin,-ymax),hi=Math.min(xmax,-ymin);s+=line(map([lo,-lo]),map([hi,-hi]),'stroke="#b68153" stroke-width="3" stroke-dasharray="7 5"');}}
 if(g.center){const[x,y]=map(g.center);s+=`<circle cx="${x}" cy="${y}" r="8" fill="#e7b45f" stroke="#805a35" stroke-width="2"/><text x="${x+10}" y="${y+18}">中心</text>`;}
 s+=showPoly(original,map,'fill="#cbdce0" fill-opacity=".4" stroke="#678c98" stroke-width="3"')+marks(original,map,'#648ca1');
 if(b.prediction&&!b.image){const [x,y]=map([Number(b.prediction.x),Number(b.prediction.y)]);s+=`<circle cx="${x}" cy="${y}" r="9" fill="none" stroke="#a488b3" stroke-width="3"/><text x="${x+10}" y="${y+16}">你的猜想</text>`;}
 if(b.image){s+=showPoly(b.image,map,'fill="#ddb78c" fill-opacity=".45" stroke="#b47844" stroke-width="3"')+marks(b.image,map,'#b47844',"′");}
 let out=svg(s,'同一坐标网格上原图和操作后的图形');if(b.measured&&b.image){const a=G.sides(original),c=G.sides(b.image),aa=G.angles(original),bb=G.angles(b.image);out+=card(`<b>对应边和角</b><p>原边：${a.map(fmt).join('、')}　→　新边：${c.map(fmt).join('、')}</p><p>原角：${aa.map(x=>fmt(x)+'°').join('、')}　→　新角：${bb.map(x=>fmt(x)+'°').join('、')}</p>`);}return out+note(b.image?'蓝色是原图，暖色是实际操作后的图形；同字母是对应点。':'先看原图，留下A点可能去的位置。');}
function mirrorView(t,b){const {svg:base,map,ymin,ymax}=gridBase(t,true);let s=base+line(map([0,ymin]),map([0,ymax]),'stroke="#b68153" stroke-width="3" stroke-dasharray="7 5"')+showPoly(t.half,map,'fill="#c9dfd7" fill-opacity=".55" stroke="#668e7e" stroke-width="3"')+marks(t.half,map,'#678e7e');const available=[...b.placed],other=t.half.map(p=>{const target=G.reflect(p,t.line);if(G.pointEq(p,target))return p;const n=available.findIndex(q=>G.pointEq(q,target));return n>=0?available.splice(n,1)[0]:(available.shift()||null);});if(other.every(Boolean)&&G.simple(other))s+=showPoly(other,map,'fill="#dec19e" fill-opacity=".38" stroke="#b47d4d" stroke-width="3"');s+=b.placed.map((p,j)=>{const[x,y]=map(p),source=t.half.findIndex(v=>G.pointEq(G.reflect(v,t.line),p)),label=source<0?'点'+(j+1):name(source)+'′';return`<circle cx="${x}" cy="${y}" r="6" fill="#bd8052" stroke="#fff" stroke-width="2"/><text x="${x+8}" y="${y-8}">${label}</text>`;}).join('');if(b.folded)for(const p of b.placed){const[x,y]=map(G.reflect(p,t.line));s+=`<circle cx="${x}" cy="${y}" r="10" fill="none" stroke="#af825e" stroke-width="3"/>`;}return svg(s,'半幅图及镜线另一侧的对应点')+note(b.folded?'橙色圆环是把你画的点折回原来一侧的位置。':'沿镜线看每个点在另一边的对应位置。');}
function positionView(t,b){const table=t.scene==='table',loc=table?[[350,102],[350,242]]:t.scene==='depth'?[[350,90],[350,245]]:[[245,175],[455,175]];let s=table?'<rect x="260" y="145" width="180" height="24" rx="3" fill="#c6a47c" stroke="#846a50" stroke-width="3"/><path d="M280 169 V260 M420 169 V260" stroke="#846a50" stroke-width="8"/>':'<rect x="295" y="125" width="110" height="100" rx="7" fill="#dbc6a8" stroke="#688b7a" stroke-width="3"/><text x="350" y="179" text-anchor="middle">盒子</text><path d="M332 315 L350 286 L368 315 Z" fill="#6e9383"/><text x="350" y="342" text-anchor="middle">观察者</text>';loc.forEach(([x,y],i)=>{s+=`<circle cx="${x}" cy="${y}" r="23" fill="${b.zone===zones(t)[i]?'#dfa96c':'#edf3e9'}" stroke="#789884" stroke-width="2" data-x="p24-place" data-index="${i}"/><text x="${x}" y="${y+5}" text-anchor="middle" pointer-events="none">${i+1}</text>`;});return svg(s,table?'桌子与可放东西的两个位置':'观察者、盒子和两个可选择位置')+note('点击图中位置，也可以使用下面的按钮。');}
function walkView(t,b){const map=([x,y])=>[250+x*50,335-y*50];let s='';for(let x=0;x<5;x++)for(let y=0;y<5;y++){const[a,c]=map([x,y]);s+=`<rect x="${a-23}" y="${c-23}" width="46" height="46" rx="6" fill="#eef2e7" stroke="#c4d5c5"/>`;}for(let i=1;i<b.states.length;i++)s+=line(map(b.states[i-1]),map(b.states[i]),'stroke="#c99b70" stroke-width="4"');const[x,y,dir]=b.state,[a,c]=map([x,y]);s+=`<g transform="translate(${a} ${c}) rotate(${dir*90})"><path d="M0 -17 L14 13 L0 7 L-14 13 Z" fill="#4f8673" stroke="#335c50" stroke-width="2"/></g>`;return svg(s,'小路上的箭头与走过的轨迹')+note(`已经做了 ${b.ops.length} 步；转弯时箭头位置不变。`);}
function miniMotif(name,angle=0,show=false){const source=G.motifs[name],ps=source.map(poly=>poly.map(p=>G.rotate(p,[0,0],angle))),scale=19,x=p=>[60+p[0]*scale,55-p[1]*scale];return`<svg viewBox="0 0 120 110" aria-hidden="true">${source.map(poly=>polygon(poly.map(x),'fill="#c9dfd5" stroke="#547d70" stroke-width="2"')).join('')}${show?ps.map(poly=>polygon(poly.map(x),'fill="none" stroke="#bd8052" stroke-width="3" stroke-dasharray="4 3"')).join(''):''}</svg>`;}
function spinView(t,b){if(t.mode==='classify'){const names=['pinwheel','heart','triangle'],labels=['风车','爱心','等边三角形'],steps=[90,180,120];return`<div class="p24-motifs">${names.map((n,i)=>`<div class="p24-motif">${miniMotif(n,steps[i],b.last===i)}<b>${labels[i]}</b><small>${b.tested.includes(i)?G.motifMatches(n,steps[i])?'转后能重合':'转后不重合':'还没试'}</small></div>`).join('')}</div>`+note('这里比较整个图形，转一整圈回到起点不算新的证据。');}
 const map=([x,y])=>[350+x*55,225-y*55];if(t.mode==='square'){const p=G.motifs.square[0],rot=p.map(x=>G.rotate(x,[0,0],b.angle));return svg(showPoly(p,map,'fill="#c4dace" fill-opacity=".5" stroke="#668c78" stroke-width="3"')+showPoly(rot,map,'fill="none" stroke="#bd8755" stroke-width="4" stroke-dasharray="6 5"')+'<circle cx="350" cy="225" r="5" fill="#4e7467"/>','正方形绕中心转动的原图与新位置')+note(`已转 ${b.angle}°；重合位置 ${b.matches.length} 次。`);}
 let s='<circle cx="350" cy="225" r="5" fill="#4e7467"/>';b.placed.forEach(i=>{const p=G.motifs.pinwheel[0].map(v=>G.rotate(v,[0,0],b.rotations[i]));s+=showPoly(p,map,'fill="#b9d6c2" fill-opacity=".75" stroke="#648675" stroke-width="3"');});return svg(s,'围着共同中心转动并放好的叶片')+note(`已放 ${b.placed.length}/4 片。相同位置会重叠。`);}
function fanView(b){if(!b.shape)return card('先选一种形状，再围着中心放几块。');const map=([x,y])=>[350+x*65,235-y*65],n=b.shape,colors=['#d9b18a','#a7cdb9','#a6bdcd','#dccf8e','#c6b5d3','#e1b3ac'];let s='';for(let i=0;i<b.count;i++)s+=showPoly(G.fanPolygon(n,i),map,`fill="${colors[i%6]}" fill-opacity=".7" stroke="#617f6f" stroke-width="2"`);s+='<circle cx="350" cy="235" r="5" fill="#446c60"/>';const total=b.count*G.interior(n),status=total===360?'刚好一整圈':total<360?`还差 ${fmt(360-total)}°`:`多了 ${fmt(total-360)}°，发生重叠`;return svg(s,'相同正多边形围绕同一个顶点')+note(`已放 ${b.count} 块 · 每个角 ${fmt(G.interior(n))}° · 合计 ${fmt(total)}°，${status}。`) +(b.runs.length?`<details class="p24-fold"><summary>查看刚才的${b.runs.length}次比较</summary>${b.runs.map(([k,c])=>{const sum=k?(c*G.interior(k)):0,how=sum===360?'刚好一圈':sum<360?'还差'+fmt(360-sum)+'°':'多了'+fmt(sum-360)+'°';return`<p>${k}边形 ${c}块：${fmt(sum)}°，${how}</p>`;}).join('')}</details>`:'');}
function tilesView(b){const map=([x,y])=>[155+x*44,400-y*44];let s='';for(let i=0;i<4;i++){const col=i%2,row=Math.floor(i/2),p=b.placements[i],label=map([col*4+2,row*4+2]);if(p===null){const tl=map([col*4,row*4+4]);s+=`<rect x="${tl[0]}" y="${tl[1]}" width="176" height="176" fill="none" stroke="#bcc9ba" stroke-dasharray="5 4"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle">位置${i+1}</text>`;}else{const poly=G.tileAt(b.amplitude,col,row,b.rotations[p]);s+=showPoly(poly,map,'fill="#b6d1bf" fill-opacity=".72" stroke="#658773" stroke-width="2"');const dir=G.rotate([3,2],[2,2],b.rotations[p]),tip=map([dir[0]+4*col,dir[1]+4*row]);s+=line(label,tip,'stroke="#587668" stroke-width="3"')+`<circle cx="${tip[0]}" cy="${tip[1]}" r="4" fill="#587668"/><text x="${label[0]+7}" y="${label[1]-9}">${p+1}</text>`;}}return svg(s,'修改边缘后实际放置和旋转的小块')+note('短线指向表示这块的朝向；重叠时颜色加深。');}
function studioView(b){const map=([x,y])=>[350+x*75,225-y*75],parts=G.studioParts(b.mirror,b.rotated);let s=line(map([-3,0]),map([3,0]),'stroke="#c7d9cc" stroke-width="2" stroke-dasharray="6 5"')+line(map([0,-2]),map([0,2]),'stroke="#b08a65" stroke-width="2" stroke-dasharray="6 5"');parts.forEach(p=>s+=showPoly(p,map,'fill="#b7d5c0" stroke="#5e8974" stroke-width="3"'));return svg(s,'翻转并旋转所得的四块图形')+note(`已构造 ${parts.length} 块；两条虚线经过旋转中心。`);}
function friezeView(b){const map=([x,y])=>[130+x*52,260-y*52];let polys=[G.baseMotif];if(b.mirror)polys.push(G.reflectedMotif);if(b.repeated)polys.push(G.motifAt(G.baseMotif,4),G.motifAt(G.reflectedMotif,4));let s=line(map([2,-1]),map([2,2]),'stroke="#ad8b68" stroke-width="2" stroke-dasharray="5 5"');polys.forEach(p=>s+=showPoly(p,map,'fill="#b6d1bf" stroke="#5c8471" stroke-width="3"'));return svg(s,'实际翻转再平移的图形花边','0 0 700 330')+note(`当前 ${polys.length} 块；虚线是第一次翻面的镜线。`);}
export function visual(t,m){const b=m.board;let v='';if(t.type==='x-p24-place')v=positionView(t,b);if(t.type==='x-p24-walk')v=walkView(t,b);if(t.type==='x-p24-grid')v=gridView(t,b);if(t.type==='x-p24-read')v=readView(t,b);if(t.type==='x-p24-distance')v=distanceView(t,b);if(t.type==='x-p24-transform')v=transformView(t,b);if(t.type==='x-p24-mirror')v=mirrorView(t,b);if(t.type==='x-p24-spin')v=spinView(t,b);if(t.type==='x-p24-fan')v=fanView(b);if(t.type==='x-p24-tiles')v=tilesView(b);if(t.type==='x-p24-frieze')v=friezeView(b);if(t.type==='x-p24-studio')v=studioView(b);return`<div class="p24-world">${v}</div>`;}
export function controls(t,m){const b=m.board,complete=done(t,m);let v='',ready=true;
 if(t.type==='x-p24-place'){v=`<div class="p24-buttons">${zones(t).map((_,i)=>btn('place',`放到位置${i+1}`,`data-index="${i}" class="${b.zone===zones(t)[i]?'on':''}"`)).join('')}</div>`;ready=b.zone!==null;}
 if(t.type==='x-p24-walk'){v=`<div class="p24-buttons">${btn('L','↶ 向左转')}${btn('F','↑ 向前一步')}${t.allowBack?btn('B','↓ 向后一步'):''}${btn('R','↷ 向右转')}${btn('undo','退回一步')}</div>`;ready=b.ops.length>=t.ops.length;}
 if(t.type==='x-p24-grid'||t.type==='x-p24-mirror'){v=f('x','横向数',m.x)+f('y','纵向数',m.y)+btn('plot','把点放上去')+btn('undo','退回一个点');if(t.type==='x-p24-grid'&&t.close)v+=btn('close','按顺序连成一圈');if(t.type==='x-p24-mirror')v+=btn('fold','折回去比较');ready=t.type==='x-p24-grid'?b.placed.length>=t.target.length&&(!t.close||b.closed):b.folded;}
 if(t.type==='x-p24-read'){v=sel('item','选一个点',m.item,t.points.map((_,i)=>[String(i),name(i)+'点']))+f('x','横向数',m.x)+f('y','纵向数',m.y)+btn('record','记下这个点');ready=b.readings.every(Boolean);}
 if(t.type==='x-p24-distance'){v=`<div class="p24-buttons">${t.segments.map(([a,c],i)=>btn('measure',`量 ${name(a)}—${name(c)}`,`data-index="${i}" class="${b.measured.includes(i)?'on':''}"`)).join('')}</div>`;ready=b.measured.length===t.segments.length;}
 if(t.type==='x-p24-transform'){
  if(!b.prediction)v=f('predX','先猜A的新横向数',m.predX)+f('predY','先猜A的新纵向数',m.predY)+btn('predict','留下猜想');
  else{const k=t.goal.kind;v=note('已留下猜想，操作后再对照。');if(k==='move')v+=f('dx','横向移动（向右为正）',m.dx)+f('dy','竖向移动（向上为正）',m.dy);if(k==='mirror')v+=sel('axis','镜线',m.axis,[['x','横轴'],['y','竖轴'],['y=x','斜线 y=x'],['y=-x','斜线 y=−x']]);if(k==='turn')v+=sel('angle','怎样转',m.angle,[['90','逆时针90°'],['-90','顺时针90°'],['180','半圈180°']])+f('cx','中心的横坐标',m.cx)+f('cy','中心的纵坐标',m.cy);if(k==='scale')v+=f('factor','放大倍数',m.factor)+f('cx','中心的横坐标',m.cx)+f('cy','中心的纵坐标',m.cy);v+=btn('operate',k==='move'?'移动':k==='mirror'?'翻过去':k==='turn'?'转一转':'放大');if(b.image&&t.needsMeasure)v+=btn('measure','量对应的边和角');}
  ready=!!b.image&&(!t.needsMeasure||b.measured);
 }
 if(t.type==='x-p24-spin'){if(t.mode==='square'){v=btn('spin','↷ 转四分之一圈');ready=b.matches.length>=4;}if(t.mode==='classify'){const labels=['风车转90°','爱心转180°','三角形转120°'];v=`<p>先逐个试转：</p><div class="p24-buttons">${labels.map((x,i)=>btn('spin',x+ (b.tested.includes(i)?' ✓':''),`data-index="${i}"`)).join('')}</div><p>圈出不到一圈就能重合的：</p><div class="p24-buttons">${['风车','爱心','等边三角形'].map((x,i)=>btn('choose',x,`data-index="${i}" class="${b.selected.includes(i)?'on':''}"`)).join('')}</div>`;ready=b.tested.length===3;}if(t.mode==='build'){v=`<div class="p24-pieces">${b.rotations.map((a,i)=>`<div><span>第${i+1}片 · ${a}°</span>${btn('pieceTurn','转90°',`data-index="${i}"`)}${btn('piecePlace',b.placed.includes(i)?'拿回':'放上',`data-index="${i}"`)}</div>`).join('')}</div>`;ready=b.placed.length===4;}}
 if(t.type==='x-p24-fan'){v=sel('kind','选一种形状',m.kind,[['3','正三角形'],['4','正方形'],['6','正六边形'],['5','正五边形']])+btn('fanChoose','换一种')+(b.shape?btn('fanAdd','再放一块')+btn('fanRecord','记下这次')+btn('fanClear','从一块开始'):'');ready=t.samples.every(s=>b.runs.some(r=>JSON.stringify(r)===JSON.stringify(s)));}
 if(t.type==='x-p24-tiles'){v=sel('amplitude','改变相对的两条边',m.amplitude,[['1','向外再向内'],['-1','向内再向外']])+btn('design','改变这一块')+sel('item','选择小块',m.item,Array.from({length:4},(_,i)=>[String(i),`小块${i+1}`]))+btn('tileTurn','转90°')+sel('slot','放到哪个位置',m.slot,Array.from({length:4},(_,i)=>[String(i),`位置${i+1}`]))+btn('tilePlace','放上去');ready=b.placements.every(x=>x!==null);}
 if(t.type==='x-p24-frieze'){v=btn('friezeMirror','把一块翻过去')+(b.mirror?btn('friezeRepeat','把这一对向右重复'):'');ready=b.repeated;}
 if(t.type==='x-p24-studio'){v=btn('studioMirror','沿竖线翻一块')+(b.mirror?btn('studioRotate','把两块转半圈'):'');ready=b.rotated;}
 v=fold(v,complete);if(ready)v+=qs(t,m);if(m.issue)v+=`<p class="p24-issue" role="status">${esc(m.issue)}</p>`;return`<div class="p24-controls">${v}<details class="p24-fold"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
